using System.ComponentModel.Composition;
using XrmToolBox.Extensibility;
using XrmToolBox.Extensibility.Interfaces;

namespace SecurityModelSync
{
    // The metadata below is what XrmToolBox shows in its tool list.
    [Export(typeof(IXrmToolBoxPlugin)),
     ExportMetadata("Name", "Security Model Sync"),
     ExportMetadata("Description", "Compare and copy business units, users, teams, queues, role assignments and memberships from one organization to another. Upsert only: nothing is deleted."),
     ExportMetadata("SmallImageBase64", SmallImage),
     ExportMetadata("BigImageBase64", BigImage),
     ExportMetadata("BackgroundColor", "Lavender"),
     ExportMetadata("PrimaryFontColor", "Black"),
     ExportMetadata("SecondaryFontColor", "Gray")]
    public class SecurityModelSyncPlugin : PluginBase
    {
        public override IXrmToolBoxPluginControl GetControl()
        {
            return new SecurityModelSyncControl();
        }

        // 32 x 32 PNG
        private const string SmallImage = "";

        // 80 x 80 PNG
        private const string BigImage = "";
    }
}
